<?php require_once 'includes/bootstrap.php'; $id=(int)($_GET['id']??0); $stmt=db()->prepare('SELECT * FROM courses WHERE id=? AND is_active=1'); $stmt->execute([$id]); $course=$stmt->fetch(); if(!$course){http_response_code(404); page_head('Course not found'); site_header(); echo '<main><section class="narrow"><div class="card center"><h1>Course not found</h1><p>The selected course is unavailable.</p><a class="button primary-button" href="'.e(url('courses.php')).'">Back to courses</a></div></section></main>'; site_footer(); exit;} page_head($course['title'],$course['short_description']); site_header('courses.php'); render_flash(); $enrolled=false; if($u=current_user()){$s=db()->prepare('SELECT 1 FROM enrollments WHERE user_id=? AND course_id=?');$s->execute([$u['id'],$id]);$enrolled=(bool)$s->fetchColumn();} ?>
<main><section class="page-hero"><div class="page-hero-content"><span class="badge"><?= e($course['level']) ?></span><h1><?= e($course['title']) ?></h1><p><?= e($course['short_description']) ?></p></div></section><section><div class="split-layout course-detail"><div><img class="rounded-image" src="<?= e(url('images/'.$course['image'])) ?>" alt="<?= e($course['title']) ?> course image"></div><div class="card"><h2>Course overview</h2><p><?= e($course['description']) ?></p><h3>Topics</h3><p><?= e($course['topics']) ?></p><p><strong>Level:</strong> <?= e($course['level']) ?></p><?php if($enrolled): ?><div class="alert success" role="status">You are enrolled in this course.</div><?php elseif(current_user()): ?><form method="post" action="enroll.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="course_id" value="<?= $id ?>"><button class="button primary-button" type="submit">Enrol in this course</button></form><?php else: ?><a class="button primary-button" href="<?= e(url('login.php?redirect=course.php%3Fid%3D'.$id)) ?>">Log in to enrol</a><?php endif; ?></div></div></section></main><?php site_footer(); ?>